// Private authoritative player HP for a future shared boss room.
// No HTTP route. Browser-supplied health, defence, hits or kills are forbidden.
// Apply only events generated by a trusted server boss AI *inside the same*
// transaction that saves the AI sequence and the player health snapshot.
import { BOSS_AI_PROFILES } from './server-boss-behavior.mjs';

const validId = s => typeof s === 'string' && s.length > 0 &&
  s.length <= 96 && s.trim() === s;
const finite = Number.isFinite;
const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
export const playerHpAt = level => 10 + Math.round(level * 1.5 + level * level / 40);
export const BOSS_STRIKE_DAMAGE = Object.freeze({
  cave: Object.freeze({ level: 40, maxHit: Math.max(1, Math.round(playerHpAt(40) * .12)) }),
  abear: Object.freeze({ level: 70, maxHit: Math.max(1, Math.round(playerHpAt(70) * .12)) })
});

const randomUnit = random => {
  const n = random();
  if (!finite(n) || n < 0 || n >= 1)
    throw new RangeError('Invalid server combat random sample');
  return n;
};
function validCharacter(value, roomId) {
  return value && value.roomId === roomId &&
    Number.isInteger(value.level) && value.level >= 1 &&
    value.level <= 100 && Number.isInteger(value.defenseTotal) &&
    value.defenseTotal >= 0 && value.defenseTotal <= 1000;
}
const copy = value => JSON.parse(JSON.stringify(value));

export class ServerPlayerHealth {
  constructor({ roomId, getVerifiedCharacter, getVerifiedPosition,
    random = Math.random }) {
    if (!validId(roomId) || typeof getVerifiedCharacter !== 'function' ||
        typeof getVerifiedPosition !== 'function' ||
        typeof random !== 'function')
      throw new TypeError('Trusted room character, position and RNG required');
    this.roomId = roomId;
    this.getVerifiedCharacter = getVerifiedCharacter;
    this.getVerifiedPosition = getVerifiedPosition;
    this.random = random;
    this.members = new Map();
    // One monotonic cursor for each unique boss spawn. This avoids an
    // unbounded list of every processed strike while preventing replays.
    this.cursors = new Map();
  }

  verifiedStats(accountId) {
    if (!validId(accountId)) throw new TypeError('Invalid account ID');
    const stats = this.getVerifiedCharacter(accountId);
    if (!validCharacter(stats, this.roomId))
      throw new TypeError('Invalid trusted character stats');
    return stats;
  }

  join(accountId) {
    const stats = this.verifiedStats(accountId);
    let member = this.members.get(accountId);
    const maxHp = playerHpAt(stats.level);
    if (member) {
      // Character progression can change between encounters/restarts. Do not
      // gift additional HP through reconnecting or overwrite a death.
      member.hp = Math.min(member.hp, maxHp);
      member.maxHp = maxHp;
    } else {
      if (this.members.size >= 64) throw new RangeError('Room health roster full');
      member = { hp: maxHp, maxHp };
      this.members.set(accountId, member);
    }
    return { accountId, ...member, alive: member.hp > 0 };
  }

  member(accountId) {
    const entry = this.members.get(accountId);
    return entry ? { accountId, hp: entry.hp, maxHp: entry.maxHp,
      alive: entry.hp > 0 } : null;
  }

  isAlive(accountId) {
    return this.members.has(accountId) && this.members.get(accountId).hp > 0;
  }

  // Internal server-only respawn hook; future service must enforce a death
  // timer and validated safe spawn position before calling it.
  respawnVerified(accountId) {
    const member = this.members.get(accountId);
    if (!member || member.hp > 0) return false;
    const stats = this.verifiedStats(accountId);
    member.maxHp = playerHpAt(stats.level);
    member.hp = member.maxHp;
    return true;
  }

  applyVerifiedStrike(strike) {
    if (!strike || strike.kind !== 'strike' ||
        !validId(strike.type) || !BOSS_STRIKE_DAMAGE[strike.type] ||
        typeof strike.key !== 'string' || strike.key.length > 1024 ||
        !Number.isSafeInteger(strike.sequence) || strike.sequence < 1 ||
        !finite(strike.x) || !finite(strike.y) ||
        strike.radius !== BOSS_AI_PROFILES[strike.type].radius ||
        !Array.isArray(strike.targets) || strike.targets.length > 64)
      throw new TypeError('Invalid trusted strike event');
    let key;
    try { key = JSON.parse(strike.key); } catch {
      throw new TypeError('Invalid strike identity');
    }
    if (!Array.isArray(key) || key.length !== 5 ||
        key[0] !== this.roomId || !validId(key[1]) ||
        !validId(key[2]) || key[3] !== 'strike' ||
        key[4] !== strike.sequence)
      throw new TypeError('Strike room or boss identity mismatch');
    const cursor = JSON.stringify([key[1], key[2]]);
    const last = this.cursors.get(cursor) ?? 0;
    if (strike.sequence <= last)
      return { applied: false, reason: 'already-processed', hits: [] };
    if (strike.sequence !== last + 1)
      throw new RangeError('Noncontiguous boss strike sequence');
    if (strike.targets.some((id, i) =>
      !validId(id) || (i > 0 && strike.targets[i - 1] >= id)))
      throw new TypeError('Strike targets must be unique and sorted');

    // Validate every recipient using trusted server positions BEFORE any HP
    // mutation or RNG. A poisoned event cannot partially damage players.
    const targets = strike.targets.map(accountId => {
      const position = this.getVerifiedPosition(accountId);
      if (!position || position.roomId !== this.roomId ||
          !finite(position.x) || !finite(position.y) ||
          Math.hypot(strike.x - position.x, strike.y - position.y) > strike.radius ||
          !this.members.has(accountId))
        throw new TypeError('Unverified strike target position');
      return { accountId, position,
        stats: this.members.get(accountId).hp > 0 ?
          this.verifiedStats(accountId) : null };
    });
    const def = BOSS_STRIKE_DAMAGE[strike.type];
    const hits = [];
    for (const { accountId, stats } of targets) {
      const member = this.members.get(accountId);
      if (member.hp === 0) continue;
      const hitChance = clamp(.75 + (def.level - stats.level) * .008 -
        stats.defenseTotal * .0012, .35, .9);
      const hit = randomUnit(this.random) < hitChance;
      let damage = 0;
      if (hit) {
        const rolled = 1 + Math.floor(randomUnit(this.random) * def.maxHit);
        const reduction = Math.min(.45,
          .5 * stats.defenseTotal / (stats.defenseTotal + 70));
        damage = Math.max(1, Math.round(rolled * (1 - reduction)));
        damage = Math.min(member.hp, damage); // never overkill player HP
        member.hp -= damage;
      }
      hits.push({
        accountId, hit, damage, hp: member.hp, maxHp: member.maxHp,
        defeated: member.hp === 0
      });
    }
    this.cursors.set(cursor, strike.sequence);
    return { applied: true, key: strike.key, hits };
  }

  exportDurableState() {
    return { schema: 1, roomId: this.roomId,
      members: [...this.members].map(([id, v]) => [id, copy(v)]),
      cursors: [...this.cursors] };
  }

  static fromDurableState(data, options) {
    const health = new ServerPlayerHealth(options);
    if (!data || data.schema !== 1 || data.roomId !== health.roomId ||
        !Array.isArray(data.members) || !Array.isArray(data.cursors) ||
        data.members.length > 64 || data.cursors.length > 2048)
      throw new TypeError('Invalid persisted health ledger');
    for (const entry of data.members) {
      if (!Array.isArray(entry) || entry.length !== 2 ||
          !validId(entry[0]) || health.members.has(entry[0]) ||
          !entry[1] || !Number.isSafeInteger(entry[1].hp) ||
          !Number.isSafeInteger(entry[1].maxHp) ||
          entry[1].maxHp < playerHpAt(1) ||
          entry[1].maxHp > playerHpAt(100) ||
          entry[1].hp < 0 || entry[1].hp > entry[1].maxHp)
        throw new TypeError('Invalid saved player HP');
      health.members.set(entry[0], copy(entry[1]));
    }
    for (const entry of data.cursors) {
      if (!Array.isArray(entry) || entry.length !== 2 ||
          typeof entry[0] !== 'string' || health.cursors.has(entry[0]) ||
          !Number.isSafeInteger(entry[1]) || entry[1] < 1)
        throw new TypeError('Invalid saved strike cursor');
      let parts;
      try { parts = JSON.parse(entry[0]); } catch {
        throw new TypeError('Invalid saved strike source');
      }
      if (!Array.isArray(parts) || parts.length !== 2 ||
          !parts.every(validId))
        throw new TypeError('Invalid saved strike source');
      health.cursors.set(entry[0], entry[1]);
    }
    return health;
  }
}
